for key,english in zip(keys,rows['en']):
 pattern=r'if \(identical\(language, "ko"\)\) statedu_utf8\("([a-f0-9]+)"\) else "'+re.escape(english)+'"'
 match=re.search(pattern,source)
 fullkey='longitudinal.help.'+key
 if match:
  korean.append(bytes.fromhex(match.group(1)).decode('utf-8'))
  source=source[:match.start()]+'statedu_t("'+fullkey+'", language)'+source[match.end():]
 else:
  assert fullkey in source
  korean.append(old_ko[fullkey])
rows['ko']=korean
for lang,values in rows.items():
 assert len(values)==len(keys)
 p=Path('i18n')/(lang+'.json');obj=json.loads(p.read_text(encoding='utf-8'))
 obj['translations'].update({'longitudinal.help.'+k:v for k,v in zip(keys,values)})
 p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
